"""Difference and sum kernel computation for a finite integer set."""
from __future__ import annotations
from typing import Dict, Iterable, Set


def sum_kernel(s: Iterable[int]) -> Dict[int, int]:
    """r^+_s(x) = #{(a,b) in s x s : a + b = x}."""
    e = list(set(s))
    k: Dict[int, int] = {}
    for a in e:
        for b in e:
            k[a + b] = k.get(a + b, 0) + 1
    return k


def difference_kernel(s: Iterable[int]) -> Dict[int, int]:
    """r^-_s(x) = #{(a,b) in s x s : a - b = x}."""
    e = list(set(s))
    k: Dict[int, int] = {}
    for a in e:
        for b in e:
            k[a - b] = k.get(a - b, 0) + 1
    return k


def support(kernel: Dict[int, int]) -> Set[int]:
    return set(kernel.keys())


if __name__ == "__main__":
    s = [1, 2, 4, 8]
    dk = difference_kernel(s)
    sk = sum_kernel(s)
    print("difference kernel:", dict(sorted(dk.items())))
    print("sum kernel       :", dict(sorted(sk.items())))
    print("|s - s| =", len(support(dk)), " |s + s| =", len(support(sk)))
    print("flat off-zero autocorrelation:",
          all(v == 1 for x, v in dk.items() if x != 0))

"""Verify the three support laws over many random Sidon and non-Sidon sets."""
from __future__ import annotations
import random
from itertools import combinations
from typing import List, Set


def is_sidon(s: List[int]) -> bool:
    seen: Set[int] = set()
    for a, b in combinations(sorted(set(s)), 2):
        if a - b in seen:
            return False
        seen.add(a - b)
    return True


def diff_card(s: List[int]) -> int:
    e = list(set(s))
    return len({a - b for a in e for b in e})


def sum_card(s: List[int]) -> int:
    e = list(set(s))
    return len({a + b for a in e for b in e})


def greedy_sidon(k: int) -> List[int]:
    """Mian-Chowla style greedy construction of a size-k Sidon set."""
    s: List[int] = []
    diffs: Set[int] = set()
    x = 0
    while len(s) < k:
        x += 1
        new = {x - y for y in s}
        if x not in s and not (new & diffs) and len(new) == len(set(new)):
            if all(d not in diffs for d in new):
                s.append(x)
                diffs |= new
                diffs |= {-d for d in new}
    return s


if __name__ == "__main__":
    for k in range(1, 9):
        s = greedy_sidon(k)
        assert is_sidon(s)
        assert diff_card(s) == k * k - k + 1
        assert 2 * sum_card(s) == k * (k + 1)
        assert 2 * sum_card(s) == diff_card(s) + 2 * k - 1
        print(f"k={k}: s={s}  |s-s|={diff_card(s)}=k^2-k+1  laws OK")

    random.seed(0)
    fails = 0
    for _ in range(2000):
        s = random.sample(range(0, 40), random.randint(1, 7))
        if diff_card(s) == len(set(s)) ** 2 - len(set(s)) + 1:
            assert is_sidon(s)
        else:
            assert not is_sidon(s)
            fails += 1
    print(f"characterization held on 2000 random sets ({fails} non-Sidon)")

