function GREEDY-SIDON(k):
    s <- [], diffs <- empty set, x <- 0
    while |s| < k:
        x <- x + 1
        new <- empty set, ok <- TRUE
        for y in s:
            d <- x - y
            if d in diffs or -d in diffs or d in new or -d in new:
                ok <- FALSE; break
            add d, -d to new
        if ok:
            append x to s; diffs <- diffs union new
    return s
